html:
{% for row in doc.rows if row.status != "Eligible" %}
<div style="{% if not loop.first %}page-break-before: always;{% endif %}">
<h3 style="text-align:center">{{ _("Attendance Shortage Notice") }}</h3>
<p style="text-align:center">{{ doc.company }} &middot; {{ doc.academic_term }}</p>
<table class="table table-bordered table-condensed">
  <tr><th>{{ _("Student") }}</th><td>{{ row.student_name }} ({{ row.student }})</td>
      <th>{{ _("Program") }}</th><td>{{ row.program }}</td></tr>
  <tr><th>{{ _("Overall attendance") }}</th><td>{{ "%.2f"|format(row.overall_pct or 0) }}%</td>
      <th>{{ _("Status") }}</th><td>{{ _(row.status) }}</td></tr>
  {% if row.shortage_summary %}<tr><th>{{ _("Courses short") }}</th><td colspan="3">{{ row.shortage_summary }}</td></tr>{% endif %}
</table>
{% if row.status == "Condonation" %}
<p>{{ _("Your attendance is in the medical band. You may apply for condonation with a medical or sports certificate; you appear in the examination only if the condonation is approved.") }}</p>
{% else %}
<p>{{ _("Your attendance is below the minimum required. You are detained for this term and may not appear in the examination.") }}</p>
{% endif %}
<p style="margin-top:40px">{{ _("Head of Department") }} &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {{ _("Principal") }}</p>
</div>
{% endfor %}
